        if((ps_sei->s_sei_ccv_params.u1_ccv_primaries_present_flag == 0) &&
           (ps_sei->s_sei_ccv_params.u1_ccv_min_luminance_value_present_flag == 0) &&
           (ps_sei->s_sei_ccv_params.u1_ccv_max_luminance_value_present_flag == 0) &&
